//! Dependency re-exports used by runbot and by code generated by its procedural macros.
//!
//! Macros expanded in a caller crate need absolute paths to Tokio, Serde, anyhow, and
//! related dependencies. These modules let callers use the same dependency versions as
//! runbot without repeating them in their own `Cargo.toml`. Only the minimum set needed by
//! generated code and examples is re-exported; the full documentation of each third-party
//! crate is not duplicated here.

/// Re-exports the `tokio` crate for generated code and asynchronous examples.
pub mod tokio {
    pub use tokio::*;
}

/// Re-exports the `tracing` crate for processor logging.
pub mod tracing {
    pub use tracing::*;
}

/// Re-exports the `anyhow` crate for processors that return `anyhow::Result`.
pub mod anyhow {
    pub use anyhow::*;
}

/// Re-exports the `serde_json` crate for request parameters and response data.
pub mod serde_json {
    pub use serde_json::*;
}

/// Re-exports the `serde` crate so generated `Serialize`/`Deserialize` implementations
/// can resolve names.
pub mod serde {
    pub use serde::*;
}

/// Re-exports the `serde_derive` derive macros, such as `Serialize` and `Deserialize`.
pub mod serde_derive {
    pub use serde_derive::*;
}

/// Re-exports the `async_trait` attribute macro used by asynchronous trait methods.
pub mod async_trait {
    pub use async_trait::*;
}
